#!/bin/bash
#
# senysisu.lock/theme-stage.sh <theme> <out-dir>
# senysisu.lock/theme-stage.sh --list
#
# Stages an installed Omarchy theme the way `omarchy theme set` would, without
# switching to it: <out-dir> is laid out like ~/.local/state/omarchy/current,
#
#   <out-dir>/theme/colors.toml   the theme's palette
#   <out-dir>/theme/shell.toml    shell surface colors (lock, …), generated by
#                                 Omarchy's own templates as on a theme switch
#   <out-dir>/background          symlink to the wallpaper
#
# so senysisu.lock and senysisu.plymouth can draw in a theme other than the
# current one. <theme> is a theme's folder name ("tokyo-night") or its name as
# `omarchy theme list` prints it ("Tokyo Night"). The wallpaper is the one
# `omarchy theme set` starts that theme with (its first background), except
# for the current theme, which keeps the wallpaper picked now.
#
# --list prints the installed themes' folder names, one per line. An unknown
# theme exits 2 with that list on stderr.
#
set -euo pipefail

OMARCHY_PATH="${OMARCHY_PATH:-/usr/share/omarchy}"
USER_THEMES="$HOME/.config/omarchy/themes"
CURRENT="$HOME/.local/state/omarchy/current"

# Same sources and precedence as omarchy-theme-list / omarchy-theme-dir.
list_themes() {
    {
        find "$USER_THEMES/" -mindepth 1 -maxdepth 1 \( -type d -o -type l \) -printf '%f\n' 2>/dev/null
        find "$OMARCHY_PATH/themes/" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null
    } | sort -u
}

if [[ ${1:-} == --list ]]; then
    list_themes
    exit 0
fi

name="${1:?usage: theme-stage.sh <theme> <out-dir> | --list}"
out="${2:?usage: theme-stage.sh <theme> <out-dir> | --list}"

# "Tokyo Night" -> "tokyo-night", as omarchy-theme-set does.
name=$(sed -E 's/<[^>]+>//g' <<<"$name" | tr '[:upper:]' '[:lower:]' | tr ' ' '-')

if [[ -d $USER_THEMES/$name ]]; then
    source_dir="$USER_THEMES/$name"
elif [[ -d $OMARCHY_PATH/themes/$name ]]; then
    source_dir="$OMARCHY_PATH/themes/$name"
else
    {
        echo "theme-stage.sh: no installed theme '$name'. Installed themes:"
        list_themes | sed 's/^/  /'
    } >&2
    exit 2
fi

rm -rf "$out"
mkdir -p "$out/theme"

# The current theme is already staged; copy it (not link: it changes on the
# next theme switch) and keep the wallpaper picked for it.
if [[ $(cat "$CURRENT/theme.name" 2>/dev/null) == "$name" && -f $CURRENT/theme/colors.toml ]]; then
    cp "$CURRENT/theme/colors.toml" "$out/theme/"
    if [[ -f $CURRENT/theme/shell.toml ]]; then cp "$CURRENT/theme/shell.toml" "$out/theme/"; fi
    wallpaper=$(readlink -f "$CURRENT/background" 2>/dev/null || true)
    if [[ -n $wallpaper && -f $wallpaper ]]; then ln -s "$wallpaper" "$out/background"; fi
    exit 0
fi

# omarchy-theme-set-templates only writes to $HOME/.local/state/omarchy/
# current/next-theme, so run it against a scratch home holding just the
# files that feed shell.toml (no theme file is executed or kept).
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT
next="$scratch/.local/state/omarchy/current/next-theme"
mkdir -p "$next" "$scratch/.config/omarchy"
if [[ -d $HOME/.config/omarchy/themed ]]; then ln -s "$HOME/.config/omarchy/themed" "$scratch/.config/omarchy/themed"; fi

for file in "$source_dir"/colors.toml "$source_dir"/shell.toml "$source_dir"/shell.*.toml; do
    if [[ -f $file && ! -L $file ]]; then cp "$file" "$next/"; fi
done
# Themes older than colors.toml: derive it from alacritty.toml, like theme-set.
if [[ ! -f $next/colors.toml && -f $source_dir/alacritty.toml && ! -L $source_dir/alacritty.toml ]]; then
    mkdir "$scratch/alacritty"
    cp "$source_dir/alacritty.toml" "$scratch/alacritty/"
    omarchy-theme-colors-from-alacritty "$scratch/alacritty" >/dev/null 2>&1 || true
    if [[ -f $scratch/alacritty/colors.toml ]]; then cp "$scratch/alacritty/colors.toml" "$next/"; fi
fi

HOME="$scratch" OMARCHY_PATH="$OMARCHY_PATH" omarchy-theme-set-templates >/dev/null 2>&1 || true

for file in colors.toml shell.toml; do
    if [[ -f $next/$file ]]; then cp "$next/$file" "$out/theme/"; fi
done

# omarchy-theme-set's choice for a theme switched to: the first background,
# user-added ones included.
wallpaper=$(find -L "$HOME/.config/omarchy/backgrounds/$name/" "$source_dir/backgrounds/" -maxdepth 1 -type f \
    \( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' -o -iname '*.gif' -o -iname '*.bmp' -o -iname '*.webp' \) \
    -print0 2>/dev/null | sort -z | tr '\0' '\n' | sed -n 1p || true)
if [[ -n $wallpaper ]]; then ln -s "$wallpaper" "$out/background"; fi
